    local profileKeys={"\x61\x64\x61\x70\x74\x69\x76\x65","\x66\x69\x78\x65\x64\x4c\x65\x61\x64","\x65\x78\x74\x72\x61\x4c\x65\x61\x64","\x70\x72\x69\x6f\x72\x69\x74\x69\x7a\x65\x50\x69\x6e\x67","\x70\x72\x65\x64\x69\x63\x74\x4a\x75\x6d\x70","\x70\x72\x65\x64\x69\x63\x74\x4c\x61\x67","\x6d\x61\x78\x53\x69\x6d\x75\x6c\x61\x74\x69\x6f\x6e\x4d\x73","\x70\x72\x65\x64\x69\x63\x74\x69\x6f\x6e\x49\x6e\x74\x65\x72\x76\x61\x6c\x4d\x73","\x6d\x61\x6e\x75\x61\x6c\x50\x69\x6e\x67\x4d\x73","\x6f\x66\x66\x73\x65\x74\x58","\x6f\x66\x66\x73\x65\x74\x59","\x6f\x66\x66\x73\x65\x74\x5a","\x68\x6f\x72\x69\x7a\x6f\x6e\x74\x61\x6c\x4d\x75\x6c\x74\x69\x70\x6c\x69\x65\x72","\x76\x65\x72\x74\x69\x63\x61\x6c\x4d\x75\x6c\x74\x69\x70\x6c\x69\x65\x72"}
    local function profileSnapshot(profile)
        local data={}
        for _,key in ipairs(profileKeys) do data[key]=profile[key] end
        return data
    end
    local function applyProfile(profile,data)
        if typeof(data)~="\x74\x61\x62\x6c\x65" then return false end
        for _,key in ipairs(profileKeys) do
            if typeof(data[key])==typeof(profile[key]) then profile[key]=data[key] end
        end
        if type(syncRevertControls)=="\x66\x75\x6e\x63\x74\x69\x6f\x6e" then syncRevertControls() end
        return true
    end
    local function profilePresetNames(kind)
        local names={"\x64\x65\x66\x61\x75\x6c\x74"}
        if type(listfiles)=="\x66\x75\x6e\x63\x74\x69\x6f\x6e" then
            ensurePresetFolder()
            local ok,files=pcall(listfiles,PRESET_FOLDER)
            if ok and typeof(files)=="\x74\x61\x62\x6c\x65" then
                local suffix="\x5f"..string.lower(kind).."\x25\x2e\x70\x72\x65\x73\x65\x74\x24"
                for _,file in ipairs(files) do
                    local base=tostring(file):gsub("\x5c","\x2f"):match("\x28\x5b\x5e\x2f\x5d\x2b\x29"..suffix)
                    if base and not table.find(names,base) then names[#names+1]=base end
                end
            end
        end
        table.sort(names)
        return names
    end
