            {"\x6b\x6e\x69\x66\x65\x2e\x70\x72\x69\x6f\x72\x69\x74\x69\x7a\x65\x50\x69\x6e\x67",config.knifeAim.prioritizePing},{"\x6b\x6e\x69\x66\x65\x2e\x70\x72\x65\x64\x69\x63\x74\x4a\x75\x6d\x70",config.knifeAim.predictJump},{"\x6b\x6e\x69\x66\x65\x2e\x70\x72\x65\x64\x69\x63\x74\x4c\x61\x67",config.knifeAim.predictLag}
