local remoteConnections = {}
function connectRemote(name, handler)
    local wanted = string.lower(tostring(name))
    local first
    for _, remote in ipairs(ReplicatedStorage:GetDescendants()) do
        if string.lower(remote.Name) == wanted then
            if remote:IsA("\x52\x65\x6d\x6f\x74\x65\x45\x76\x65\x6e\x74") then
                first = first or remote
                table.insert(remoteConnections, remote.OnClientEvent:Connect(function(...) pcall(handler, ...) end))
            elseif remote:IsA("\x42\x69\x6e\x64\x61\x62\x6c\x65\x45\x76\x65\x6e\x74") then
                first = first or remote
                table.insert(remoteConnections, remote.Event:Connect(function(...) pcall(handler, ...) end))
            end
        end
    end
    return first
end

connectRemote("\x50\x6c\x61\x79\x65\x72\x44\x61\x74\x61\x43\x68\x61\x6e\x67\x65\x64", function(first, second)
    if typeof(second) == "\x74\x61\x62\x6c\x65" and typeof(first) == "\x49\x6e\x73\x74\x61\x6e\x63\x65" and first:IsA("\x50\x6c\x61\x79\x65\x72") then
        consumeData({ [first.Name] = second }, false)
    else
        consumeData(first, false)
    end
end)
