local Maid = {}
Maid.__index = Maid

function Maid.new()
    return setmetatable({_tasks = {}, _destroyed = false}, Maid)
end

function Maid:GiveTask(task)
    if self._destroyed then
        self:_cleanupTask(task)
        return
    end
    table_insert(self._tasks, task)
    return task
end

function Maid:GiveTasks(...)
    for _, task in ipairs({...}) do
        self:GiveTask(task)
    end
end

function Maid:_cleanupTask(task)
    local taskType = typeof(task)
    if taskType == "\x52\x42\x58\x53\x63\x72\x69\x70\x74\x43\x6f\x6e\x6e\x65\x63\x74\x69\x6f\x6e" then
        task:Disconnect()
    elseif taskType == "\x49\x6e\x73\x74\x61\x6e\x63\x65" then
        task:Destroy()
    elseif taskType == "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then
        task()
    elseif taskType == "\x74\x61\x62\x6c\x65" and type(task.Destroy) == "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then
        task:Destroy()
    end
end

function Maid:DoCleaning()
    if self._destroyed then return end
    self._destroyed = true
    for _, task in ipairs(self._tasks) do
        self:_cleanupTask(task)
    end
    self._tasks = {}
end

function Maid:Destroy()
    self:DoCleaning()
end

