    local scalars = {
        "\x66\x6c\x69\x6e\x67\x44\x75\x72\x61\x74\x69\x6f\x6e", "\x66\x6c\x69\x6e\x67\x50\x6f\x77\x65\x72", "\x66\x6c\x69\x6e\x67\x4d\x65\x74\x68\x6f\x64", "\x70\x72\x65\x64\x69\x63\x74\x69\x6f\x6e\x53\x74\x75\x64\x73", "\x73\x74\x61\x72\x74\x53\x74\x75\x64\x73", "\x61\x75\x74\x6f\x52\x65\x74\x75\x72\x6e",
        "\x6c\x6f\x6f\x70\x49\x6e\x74\x65\x72\x76\x61\x6c", "\x61\x75\x72\x61\x49\x6e\x74\x65\x72\x76\x61\x6c", "\x61\x75\x72\x61\x53\x74\x75\x64\x73",
        "\x62\x69\x6e\x64\x42\x75\x74\x74\x6f\x6e\x53\x69\x7a\x65", "\x74\x61\x72\x67\x65\x74\x43\x6f\x6f\x6c\x64\x6f\x77\x6e",
        "\x61\x75\x74\x6f\x53\x68\x65\x72\x69\x66\x66\x44\x65\x6c\x61\x79", "\x61\x75\x74\x6f\x4d\x75\x72\x64\x65\x72\x65\x72\x44\x65\x6c\x61\x79", "\x72\x6f\x6c\x65\x43\x61\x63\x68\x65\x54\x54\x4c",
