    end
     
    if type(config.flingDuration)=="\x6e\x75\x6d\x62\x65\x72" then config.flingDuration=math.clamp(math.floor(config.flingDuration+0.5),1,5) end
    if type(config.flingPower)=="\x6e\x75\x6d\x62\x65\x72" then config.flingPower=math.clamp(math.floor(config.flingPower+0.5),1,3) end
