    if type(config.startStuds)=="\x6e\x75\x6d\x62\x65\x72" then config.startStuds=math.clamp(config.startStuds,-5,20) end
    local METHODS = { Auto=true, Fling=true, Sweep=true }
    if type(config.flingMethod)~="\x73\x74\x72\x69\x6e\x67" or not METHODS[config.flingMethod] then config.flingMethod="\x41\x75\x74\x6f" end
    if type(data.keybinds) == "\x74\x61\x62\x6c\x65" then config.keybinds = data.keybinds end
    if type(data.bindPositions) == "\x74\x61\x62\x6c\x65" then config.bindPositions = data.bindPositions end
    if type(data.hudPos) == "\x74\x61\x62\x6c\x65" and type(data.hudPos.x) == "\x6e\x75\x6d\x62\x65\x72" and type(data.hudPos.y) == "\x6e\x75\x6d\x62\x65\x72" then
        config.hudPos = { x = data.hudPos.x, y = data.hudPos.y }
    end
    if type(data.pluginUI)=="\x74\x61\x62\x6c\x65" then config.pluginUI=data.pluginUI end
    loadedWhitelist = unpackWhitelist(data.whitelist)
    return true
end

local function loadConfig()
    if not canPersist or type(isfile) ~= "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then return false end
    local applied = false
