local Ticker = { _fns = {}, _conn = nil }

function Ticker._start()
    if Ticker._conn then return end
    Ticker._conn = RunService.RenderStepped:Connect(function(dt)
        local fns = Ticker._fns
        local i = 1
        while i <= #fns do
            local fn = fns[i]
            if fn then
                local ok, err = xpcall(fn, debug.traceback, dt)
                if not ok then
                    warn("\x5b" .. BRAND .. "\x5d\x5b\x74\x69\x63\x6b\x65\x72\x5d\x20" .. tostring(err))
                    table.remove(fns, i)
                    i = i - 1
                end
            end
            i = i + 1
        end
        if #fns == 0 and Ticker._conn then
            Ticker._conn:Disconnect()
            Ticker._conn = nil
        end
    end)
end

function Ticker.add(fn)
    if type(fn) ~= "\x66\x75\x6e\x63\x74\x69\x6f\x6e" then return function() end end
    local fns = Ticker._fns
    fns[#fns + 1] = fn
    Ticker._start()
    local removed = false
    return function()
        if removed then return end
        removed = true
        for i = 1, #fns do
            if fns[i] == fn then
                table.remove(fns, i)
                break
            end
        end
    end
end

RootMaid:GiveTask(function()
