    ripple.BackgroundTransparency = 0.45
    ripple.Size = ud2(0, 0, 0, 0)
    ripple.AnchorPoint = v2(0.5, 0.5)
    ripple.Visible = false
    ripple.ZIndex = 2
    ripple.Parent = ImageButton
