local function isValidTarget(player)
    if not player or player == LocalPlayer or not player.Parent then return false end
    if state.whitelist[player.UserId] then return false end
    local char = player.Character
    if not char then return false end
    if not char:FindFirstChild("\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74") then return false end
    local hum = char:FindFirstChildOfClass("\x48\x75\x6d\x61\x6e\x6f\x69\x64")
    if hum and hum.Health <= 0 then return false end
    return true
end

local function getSelectedOrFirst()
    if isValidTarget(state.resetSelPlr) then return state.resetSelPlr end
    for _, player in ipairs(state.selectedPlayers) do
        if isValidTarget(player) then return player end
    end
    return nil
end

local function findNearest()
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74")
    if not root then return nil end
    local best, bestDist = nil, math.huge
    local players = Players:GetPlayers()
    for i = 1, #players do
        local player = players[i]
        if isValidTarget(player) then
            local tr = player.Character and player.Character:FindFirstChild("\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74")
            if tr then
                local d = (root.Position - tr.Position).Magnitude
                if d < bestDist then best, bestDist = player, d end
            end
        end
    end
    return best
end

 
local roleRemote = nil
local roleRemoteTried = -1e9
local function getRoleRemote()
    if roleRemote and roleRemote.Parent then return roleRemote end
    local t = now()
    if (t - roleRemoteTried) < 5 then return roleRemote end
    roleRemoteTried = t
    pcall(function()
        local remote = ReplicatedStorage:FindFirstChild("\x47\x65\x74\x50\x6c\x61\x79\x65\x72\x44\x61\x74\x61", true)
        if remote and remote:IsA("\x52\x65\x6d\x6f\x74\x65\x46\x75\x6e\x63\x74\x69\x6f\x6e") then roleRemote = remote end
    end)
    return roleRemote
end

local roleCache = { data = nil, timestamp = 0 }
local function getCachedRoleData()
    local t = now()
    local ttl = config.roleCacheTTL or 0.8
    if roleCache.data and (t - roleCache.timestamp) < ttl then return roleCache.data end
    local remote = getRoleRemote()
    if remote then
        local ok, result = pcall(function() return remote:InvokeServer() end)
        if ok and type(result) == "\x74\x61\x62\x6c\x65" then
            roleCache.data, roleCache.timestamp = result, t
            return result
        end
    end
    roleCache.timestamp = t
    return roleCache.data
end

local function invalidateRoleCache()
    roleCache.data = nil
    roleCache.timestamp = 0
end

local function hasGunModel(char)
    if not char then return false end
    if char:FindFirstChild("\x47\x75\x6e") or char:FindFirstChild("\x52\x65\x76\x6f\x6c\x76\x65\x72") then return true end
    local tool = char:FindFirstChildOfClass("\x54\x6f\x6f\x6c")
    if tool then
        local name = tool.Name:lower()
        if name:find("\x67\x75\x6e", 1, true) or name:find("\x72\x65\x76\x6f\x6c\x76\x65\x72", 1, true) then return true end
    end
    return false
end

local function quickScanSheriff()
    local players = Players:GetPlayers()
    for i = 1, #players do
        local player = players[i]
        if player ~= LocalPlayer and not state.whitelist[player.UserId] then
            if hasGunModel(player.Character) then return player end
            local bp = player:FindFirstChild("\x42\x61\x63\x6b\x70\x61\x63\x6b")
            if bp and (bp:FindFirstChild("\x47\x75\x6e") or bp:FindFirstChild("\x52\x65\x76\x6f\x6c\x76\x65\x72")) then
                return player
            end
        end
    end
    return nil
end

local function findTargetByRole(roleName)
    local roleData = getCachedRoleData()
    if not roleData then return nil end
    for playerName, data in pairs(roleData) do
        if type(data) == "\x74\x61\x62\x6c\x65" and data.Role == roleName and not data.Killed and not data.Dead then
            local p = Players:FindFirstChild(playerName)
            if p and p ~= LocalPlayer and not state.whitelist[p.UserId] then return p end
        end
    end
    return nil
end

local sheriffCache = { player = nil, at = 0 }
local function findSheriff()
    local t = now()
    if sheriffCache.player and (t - sheriffCache.at) < 0.35 and isValidTarget(sheriffCache.player) then
        return sheriffCache.player
    end
    local found = quickScanSheriff()
    if not found then found = findTargetByRole("\x53\x68\x65\x72\x69\x66\x66") end
    sheriffCache.player, sheriffCache.at = (isValidTarget(found) and found or nil), t
    return sheriffCache.player
end

local function findMurderer()
    local byRole = findTargetByRole("\x4d\x75\x72\x64\x65\x72\x65\x72")
    if byRole then return byRole end
    local players = Players:GetPlayers()
    for i = 1, #players do
        local player = players[i]
        if player ~= LocalPlayer and not state.whitelist[player.UserId] then
            local char = player.Character
            if char then
                local tool = char:FindFirstChildOfClass("\x54\x6f\x6f\x6c")
                if tool then
                    local name = tool.Name:lower()
                    if name:find("\x6b\x6e\x69\x66\x65", 1, true) or name:find("\x6d\x75\x72\x64\x65\x72\x65\x72", 1, true) then
                        return player
                    end
                end
            end
        end
    end
    return nil
end

 
