    if not enabled then stopAutoModule("\x6c\x6f\x6f\x70\x50\x6c\x72") return end
    local idx=1
    startAutoModule("\x6c\x6f\x6f\x70\x50\x6c\x72", function()
        if isValidTarget(state.resetSelPlr) then return state.resetSelPlr end
        local list=state.selectedPlayers
        for _=1,#list do
            idx=((idx-1)%#list)+1
            local p=list[idx]
            if isValidTarget(p) then return p end
