autoSection:AddToggle("\x41\x75\x72\x61", function(enabled)
    if not enabled then stopAutoModule("\x61\x75\x72\x61") return end
    startAutoModule("\x61\x75\x72\x61", function()
        local char=LocalPlayer.Character
        local root=char and char:FindFirstChild("\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74")
        if not root then return nil end
        local myPos=root.Position
        local maxSq=(config.auraStuds or 15)^2
        local best,bestDist=nil,maxSq
        local players=Players:GetPlayers()
        for i=1,#players do
            local player=players[i]
            if isValidTarget(player) then
                local tr=player.Character and player.Character:FindFirstChild("\x48\x75\x6d\x61\x6e\x6f\x69\x64\x52\x6f\x6f\x74\x50\x61\x72\x74")
                if tr then
                    local d=(myPos-tr.Position).Magnitude
                    local dsq=d*d
                    if dsq<=bestDist then best,bestDist=player,dsq end
                end
            end
        end
        return best
    end, function() return config.auraInterval end)
end)
autoSection:AddToggle("\x43\x6c\x69\x63\x6b", function(enabled)
    if maids.clickFling then maids.clickFling:Destroy(); maids.clickFling=nil end
    if not enabled then return end
    maids.clickFling=Maid.new()
    local camera=Workspace.CurrentCamera
    local rayParams=RaycastParams.new()
    rayParams.FilterType=Enum.RaycastFilterType.Exclude
    rayParams.IgnoreWater=true
    local function resolveTarget()
        local char=LocalPlayer.Character
        rayParams.FilterDescendantsInstances=char and {char} or {}
        local mouse=LocalPlayer:GetMouse()
        if camera and mouse then
            local unit=camera:ViewportPointToRay(mouse.X, mouse.Y, 1000)
            local hit=Workspace:Raycast(unit.Origin, unit.Direction*1000, rayParams)
            if hit and hit.Instance then
                local model=hit.Instance:FindFirstAncestorWhichIsA("\x4d\x6f\x64\x65\x6c")
                local player=model and Players:GetPlayerFromCharacter(model)
                if player then return player end
            end
        end
        local target=mouse and mouse.Target
        local model=target and target:FindFirstAncestorWhichIsA("\x4d\x6f\x64\x65\x6c")
        local player=model and Players:GetPlayerFromCharacter(model)
        return player or nil
    end
    local function onInput(input, processed)
        if processed then return end
        if input.UserInputType ~= MOUSE1 and input.UserInputType ~= TOUCH then return end
        local ok, player=pcall(resolveTarget)
        if not ok or not player or player==LocalPlayer then return end
        state.resetSelPlr=player
        if state.whitelist[player.UserId] then Notify("\x43\x6c\x69\x63\x6b", player.Name.."\x20\x69\x73\x20\x77\x68\x69\x74\x65\x6c\x69\x73\x74\x65\x64\x21",3)
        else SkidFling(player); Notify("\x43\x6c\x69\x63\x6b","\x46\x6c\x69\x6e\x67\x69\x6e\x67\x20"..player.Name,2) end
    end
    maids.clickFling:GiveTask(UserInputService.InputBegan:Connect(onInput))
end)

 
